            out.append(inner);
            out.push(&format!("; Ok::<_, {}>(__nikaia_task) }}", scope.channel));
            out.push(&format!(", |e: &{}| {{ use nikaia_std::task::{{ProbeEnding as _, ProbePlain as _}}; (&&nikaia_std::task::Probe(e)).report() }})", scope.channel));
