pub(crate) fn emit_is_fatal(ledger: &Ledger, error: &str) -> bool {
    let types = match ledger.implementations.get("Fatal") { Some(__nikaia_value) => __nikaia_value, None => return false };
    types.contains(error)
}

pub(crate) fn emit_join_receiver(world: &EmitWorld<'_, '_, '_, '_>, guarded: &Expr) -> String {
    match guarded {
        Expr::MethodCall { receiver, config, .. } => { let receiver = nikaia_std::boxed::open(receiver); match receiver {
            Expr::Variable(name, _) if config.is_empty() => { let name = *name; emit_text(world, name).to_owned() },
            _ => "".to_owned(),
        } },
        _ => "".to_owned(),
    }
}

pub(crate) fn emit_catch_is_a_scope(world: &EmitWorld<'_, '_, '_, '_>, guarded: &Expr) -> bool {
    match guarded {
        Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); unaliased_in(world.aliases, &nikaia_std::index::or(emit_callee_text(world, func), || "".into())) == "task::scope" },
        _ => false,
    }
}

impl EmitState {
    pub(crate) fn emit_catch_calls_given_code(&self, world: &EmitWorld<'_, '_, '_, '_>, guarded: &Expr) -> bool {
        let name = match call_callee_name(world.words, world.aliases, guarded) { Some(__nikaia_value) => __nikaia_value, None => return false };
        let mut set: Vec<String> = vec![];
        let own = self.own_contracts.functions.get(&name);
        if own.is_some() { set = match own { Some(__nikaia_value) => __nikaia_value, None => return false }.fails_with.to_owned(); } else {
            let theirs = match world.library.functions.get(&name) { Some(__nikaia_value) => __nikaia_value, None => return false };
            set = theirs.fails_with.to_owned();
        }
        for member in set.iter() { if throws_given(member) { return true; } }
        false
    }
    pub(crate) fn emit_catch_is_a_field_call(&self, guarded: &Expr) -> bool {
        match guarded {
            Expr::MethodCall { receiver, .. } => { let receiver = nikaia_std::boxed::open(receiver); self.facts.field_calls.contains_key(&node_key(receiver)) },
            Expr::Call { func, .. } => { let func = nikaia_std::boxed::open(func); self.facts.kept_calls.contains_key(&node_key(func)) || self.facts.run_code_fails.contains(&node_key(func)) },
            _ => false,
        }
    }
}

pub(crate) fn emit_catch_is_a_join(world: &EmitWorld<'_, '_, '_, '_>, guarded: &Expr) -> bool {
    match guarded {
        Expr::MethodCall { method, .. } => { let method = *method; emit_text(world, method) == "join" },
        _ => false,
    }
}

pub(crate) fn emit_flow_operated(expr: &Expr) -> bool { matches!(expr, Expr::Binary { .. } | Expr::Unary { .. }) }

